package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body)
            throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + from);
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty()) {
            if (!terms.matches("\\d{1,5}")) {
                throw new InvalidPersonException("Terms must be a whole number of days: " + terms);
            }
            terms = String.valueOf(Integer.parseInt(terms));
        }
        body.set(new PersonRequest(name, grade, from.isEmpty() ? null : from, terms.isEmpty() ? null : terms,
                request.version()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, PersonRepository people,
            SheetRepository sheets)
            throws InvalidPersonException, PersonConflictException {
        if (request.version() != null && request.version() != person.getVersion()) {
            throw new PersonConflictException(person.getId());
        }
        if (people.nameTaken(person.getSheetId(), request.name(), person.getId())) {
            throw new InvalidPersonException("The name is already in use");
        }
        person.setName(request.name());
        person.giveTerms(request.terms() == null ? null : Integer.valueOf(request.terms()));
        // The form's grade is given from its from-date (blank: the sheet's today); a save leaving
        // the grade as the row showed it, with no from-date, gives none.
        if (request.gradeFrom() != null || !request.grade().equals(person.getGrade())) {
            java.time.LocalDate today = sheets.today(person.getSheetId());
            person.giveGrade(request.grade(), request.gradeFrom() != null ? request.gradeFrom() : today.toString(), today);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

public class SavePerson {
    public void save(@RequestParam(name = "by", required = false) String by, @Val Person person,
            PersonRepository people) throws PersonConflictException {
        if (!people.update(person)) {
            throw new PersonConflictException(person.getId()); // saved by someone else meanwhile
        }
        if (person.getRecorded() != null) {
            people.saveGrade(person, person.getRecorded(), by == null ? "" : by);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a change that went through is recorded. */
public class RecordPersonEdited {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : ""));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<Person> response) {
        response.send(person);
    }
}
package net.officefloor.hq.app.person;

/** Body of an add or edit of a person. An edit carries the version of the person its form loaded,
 *  and the date its grade applies from (blank: the sheet's today; an add's grade applies from the
 *  beginning of time), and their own terms in whole days (null: none). */
public record PersonRequest(String name, String grade, String gradeFrom, String terms, Long version) {
}
package net.officefloor.hq.app.person;

/** A grade a person was given, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
public record GradeFrom(String grade, String from) {
}

