package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a bulk grade with no one selected, a grade not A, B or C, or a from-date not a date. */
public class ValidateBulkGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeRequest> body)
            throws InvalidPersonException {
        List<Long> ids = request == null || request.personIds() == null ? List.of()
                : request.personIds().stream().filter((id) -> id != null).toList();
        if (ids.isEmpty()) {
            throw new InvalidPersonException("Select the people to grade");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + from);
            }
        }
        body.set(new BulkGradeRequest(ids, grade, from.isEmpty() ? null : from));
    }
}
EOF
cat > $P/BulkGradePeople.java <<'EOF'
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Gives the selected people the grade in list order (the order they were added), each as the
 *  person form would (see {@link ApplyPerson}: from the from-date, blank the sheet's today) and
 *  recorded as it would record it (its PERSON_EDITED line, then the rollup lines it moved). A
 *  selected id not on the sheet is skipped. */
public class BulkGradePeople {
    public void grade(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, @Val BulkGradeRequest request,
            PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Audit audit, Out<BulkGradeResult> result)
            throws PersonConflictException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        Set<Long> selected = new HashSet<>(request.personIds());
        LocalDate today = sheets.today(id);
        String from = request.from() != null ? request.from() : today.toString();
        int graded = 0;
        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings);
        for (Person listed : people.list(id)) {
            if (!selected.contains(listed.getId())) continue;
            Person person = people.find(id, listed.getId());
            person.giveGrade(request.grade(), from, today);
            if (!people.update(person)) {
                throw new PersonConflictException(person.getId());
            }
            people.saveGrade(person, person.getRecorded(), user);
            graded++;
            audit.record("PERSON_EDITED sheet=" + id + " by=" + user + " name=" + person.getName()
                    + " grade=" + person.getGrade());
            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
            for (String line : after.changesSince(before, id, user)) {
                audit.record(line);
            }
            before = after;
        }
        result.set(new BulkGradeResult(graded));
    }
}
EOF
